library(rvest);library(dplyr);library(jsonlite)
if(!exists('post_dir'))post_dir<-normalizePath('.',winslash='/')
raw<-file.path(post_dir,'data/raw')
manifest<-read.csv(file.path(raw,'manifest.csv'));stopifnot(identical(unname(tools::md5sum(file.path(raw,manifest$file))),manifest$md5))
num<-function(x)as.numeric(gsub('[^0-9.-]','',x))
parse_date<-function(x)as.Date(x,format='%b %d, %Y')
prices<-bind_rows(lapply(c('BAC','C','COF','ALLY','AXP','KBE'),function(t){d<-read_html(file.path(raw,paste0(t,'_prices.html')));x<-html_table(html_element(d,'table'));stopifnot(all(c('Date','Real price','Adjusted price')%in%names(x)));data.frame(ticker=t,month=x$Date,price=num(x[['Real price']]),adjusted=num(x[['Adjusted price']]))}))
divs<-bind_rows(lapply(c('BAC','C','COF','ALLY','AXP','KBE'),function(t){d<-read_html(file.path(raw,paste0(t,'_dividends.html')));tabs<-html_table(html_elements(d,'table'),fill=TRUE);a<-Filter(function(x)'Ex-Dividend Date'%in%names(x),tabs);stopifnot(length(a)==1);x<-a[[1]];data.frame(ticker=t,ex_date=parse_date(x[[1]]),amount=num(x[[2]]),pay_date=parse_date(x[['Pay Date']]))}))
eps<-read.csv(file.path(post_dir,'data/eps_2023_source_ledger.csv'))
h<-fromJSON(file.path(raw,'holdings.json'))$data
hold<-as.data.frame(h,stringsAsFactors=FALSE);names(hold)<-c('ticker','issuer','class','cusip','value_thousands','weight_rounded','shares','principal','option_type');hold$value_thousands<-num(hold$value_thousands);hold$shares<-num(hold$shares)
x<-eps|>left_join(hold,by='ticker')|>left_join(prices|>filter(month=='August 2024')|>select(ticker,entry_price=price),by='ticker')|>left_join(prices|>filter(month=='August 2025')|>select(ticker,exit_price=price),by='ticker')
d<-divs|>filter(ex_date>as.Date('2024-08-30'),ex_date<=as.Date('2025-08-29'))|>group_by(ticker)|>summarise(dividends=sum(amount),n_dividends=n())
x<-x|>left_join(d,by='ticker')|>mutate(pe=entry_price/eps_2023,return=(exit_price-entry_price+dividends)/entry_price)|>arrange(pe)|>mutate(selected=row_number()<=2)
bm<-prices|>filter(ticker=='KBE',month%in%c('August 2024','August 2025'));br<-(bm$price[bm$month=='August 2025']-bm$price[bm$month=='August 2024']+d$dividends[d$ticker=='KBE'])/bm$price[bm$month=='August 2024']

stopifnot(nrow(x)==5L,!anyDuplicated(x$ticker),all(is.finite(x$pe)),all(x$eps_2023>0),all(x$n_dividends==4),all(as.Date(x$public_date)<as.Date('2024-08-30')))
history_meta<-read_html(file.path(raw,'holdings.html'))
labels<-html_text2(html_elements(history_meta,'dt'));values<-html_text2(html_elements(history_meta,'dd'))
stopifnot(values[labels=='Date filed']=='8/14/2024',values[labels=='Holdings as of']=='6/30/2024',nrow(hold)==41L)
x<-x|>mutate(holding_weight=100*value_thousands/sum(hold$value_thousands),excess_pp=100*(return-br))
selected_return<-mean(x$return[x$selected]);all_return<-mean(x$return)
summary<-data.frame(group=c('Lowest two P/E holdings','All five holdings','KBE bank ETF'),n=c(2,5,1),return=c(selected_return,all_return,br))
sensitivity<-bind_rows(lapply(1:5,function(k)data.frame(lowest_n=k,return=mean(x$return[seq_len(k)]),excess_pp=100*(mean(x$return[seq_len(k)])-br))))
checks<-data.frame(check=c('Snapshot hashes match','41 filing holdings and five unique sample issuers','Historical filing and earnings predate entry','Positive originally reported EPS','Four eligible dividends per security','Selected basket equals equal-weight mean','All cases retained through exit','Dividend-inclusive return identity'),passed=c(TRUE,nrow(hold)==41&&nrow(x)==5,all(as.Date(x$public_date)<as.Date('2024-08-30')),all(x$eps_2023>0),all(x$n_dividends==4),abs(selected_return-sum(x$return[x$selected])/2)<1e-12,nrow(x)==5,all(abs(x$return-((x$exit_price+x$dividends)/x$entry_price-1))<1e-12)))
stopifnot(all(checks$passed))
for(folder in c('results','figures','data/processed'))dir.create(file.path(post_dir,folder),recursive=TRUE,showWarnings=FALSE)
write.csv(x,file.path(post_dir,'data/processed/case_data.csv'),row.names=FALSE)
write.csv(prices,file.path(post_dir,'data/processed/prices.csv'),row.names=FALSE)
write.csv(divs,file.path(post_dir,'data/processed/dividends.csv'),row.names=FALSE)
write.csv(hold,file.path(post_dir,'data/processed/all_filing_holdings.csv'),row.names=FALSE)
write.csv(summary,file.path(post_dir,'results/portfolio_returns.csv'),row.names=FALSE)
write.csv(sensitivity,file.path(post_dir,'results/screen_sensitivity.csv'),row.names=FALSE)
write.csv(checks,file.path(post_dir,'results/validation.csv'),row.names=FALSE)
write.csv(x|>select(ticker,company,pe,selected,holding_weight,entry_price,exit_price,dividends,return,excess_pp,source_url),file.path(post_dir,'results/investor_review.csv'),row.names=FALSE)
writeLines(capture.output(sessionInfo()),file.path(post_dir,'results/sessionInfo.txt'))
library(ggplot2)
plot<-x|>mutate(label=paste0(ticker,'  |  ',sprintf('%.1f',pe),'x'),label=factor(label,levels=rev(label)),group=ifelse(selected,'Lowest two P/E','Other disclosed holdings'))
g<-ggplot(plot,aes(y=label,x=100*return,fill=group))+geom_vline(xintercept=0,colour='#cbd5e1')+geom_col(width=.6)+geom_vline(xintercept=100*br,linetype='dashed',colour='#9a3412',linewidth=.8)+geom_text(aes(label=sprintf('%.1f%%',100*return)),hjust=ifelse(plot$return>=0,-.15,1.15),size=4)+scale_fill_manual(values=c('Lowest two P/E'='#176b91','Other disclosed holdings'='#a8b4c4'))+scale_x_continuous(limits=c(-9,66),breaks=c(0,20,40,60))+labs(title='The two lowest-P/E holdings beat the bank ETF in this case',subtitle='Individual dividend-inclusive returns | August 2024 to August 2025',x='One-year return (%)',y='Ticker | entry price / FY2023 diluted EPS',fill=NULL,caption=paste0('Dashed line: KBE ',sprintf('%.1f',100*br),'%. Two-stock equal-weight basket: ',sprintf('%.1f',100*selected_return),'%.
Dividends earned are not reinvested. Sources: scraped price and dividend tables; original EPS ledger.'))+theme_minimal(base_size=12)+theme(legend.position='bottom',panel.grid.minor=element_blank(),plot.title=element_text(face='bold'),plot.caption=element_text(hjust=0,size=9))
ggsave(file.path(post_dir,'figures/one_year_outcomes.png'),g,width=10,height=6,dpi=180)
f1<-function(z)sprintf('%.1f',z);f2<-function(z)sprintf('%.2f',z)
v<-function(t,col)x[x$ticker==t,col][[1]]
